insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('204512b4-e03a-4886-a44b-a48452f193cf', 'a1e5f658-2e69-46ef-bd0c-1df0f1bcd1a6', $$inleiding: krapte op de arbeidsmarkt voor verpleegkundigen, inhuren van zzp'ers$$,
   $$bedrijfseconomie-vwo-2021-iii-carolusumc-context1.png$$,
   $$Ziekenhuizen hebben grote moeite met het aantrekken én het in dienst houden van personeel. Er heerst krapte op de arbeidsmarkt voor verpleegkundigen. Daardoor zien veel ziekenhuizen zich steeds vaker genoodzaakt om verpleegkundigen als zzp’ers in te huren.$$, 'inline'),
  ('24ef0ccc-4b66-49e0-9309-10804d564766', 'a1e5f658-2e69-46ef-bd0c-1df0f1bcd1a6', $$CarolusUMC huurt een headhunter in voor personeel met vast dienstverband$$,
   $$bedrijfseconomie-vwo-2021-iii-carolusumc-context2.png$$,
   $$Het Carolus Universitair Medisch Centrum (CarolusUMC) geeft er de voorkeur aan om personeel aan te nemen met een dienstverband voor onbepaalde tijd. Voor het aantrekken hiervan heeft het een zogenaamde headhunter, een extern bureau, ingehuurd. Het inhuren van een headhunter brengt flinke kosten met zich mee.$$, 'inline'),
  ('ad870047-d70a-49b7-a7e2-e3005cc18fe2', 'a1e5f658-2e69-46ef-bd0c-1df0f1bcd1a6', $$personeelsadvertentie anesthesiemedewerker CarolusUMC$$,
   $$bedrijfseconomie-vwo-2021-iii-carolusumc-context3.png$$,
   $$In samenspraak met het CarolusUMC plaatst de headhunter onderstaande personeelsadvertentie voor een anesthesiemedewerker voor de afdeling Operatiekamers.
Persoonlijke zorg vraagt een zorgzaam persoon.
Persoonlijke zorg is een kernwaarde van het CarolusUMC. Iedereen die betrokken is bij het CarolusUMC houdt hier continu rekening mee, zowel in aandacht voor onze cliënten als in aandacht voor ons personeel.
Functieomschrijving
− Je begeleidt cliënten persoonlijk naar en door de anesthesie.
− Je werkt in teamverband en stuurt een team aan.
− Je bent actief betrokken bij opleiding van studenten.
Arbeidsvoorwaarden
− Direct een contract voor onbepaalde tijd.
− Afhankelijk van kennis en ervaring vindt inschaling plaats in schaal 9.
− Wij bieden nieuwe medewerkers van het CarolusUMC de mogelijkheid van woonruimte voor maximaal 1 jaar, totdat ze zelf iets anders hebben gevonden.
− CarolusUMC heeft voor het hele personeel een collectieve aansprakelijkheidsverzekering afgesloten.$$, 'inline'),
  ('a86c8db6-ba16-45f1-af5d-931c52d9fa6a', 'a1e5f658-2e69-46ef-bd0c-1df0f1bcd1a6', $$Emma vraagt zich af hoe de kernwaarde 'persoonlijke zorg voor het personeel' waargemaakt wordt$$,
   $$bedrijfseconomie-vwo-2021-iii-carolusumc-context4.png$$,
   $$Emma is op zoek naar een nieuwe baan, leest de advertentie en vraagt zich af hoe de kernwaarde ‘persoonlijke zorg voor het personeel’ waargemaakt kan worden in een grote en hiërarchische organisatie als een academisch ziekenhuis.$$, 'inline'),
  ('864ce91b-c57b-4216-9884-d1f7486d1c55', 'a1e5f658-2e69-46ef-bd0c-1df0f1bcd1a6', $$personeelsbeleid: mogelijkheid tot professionele ontwikkeling$$,
   $$bedrijfseconomie-vwo-2021-iii-carolusumc-context5.png$$,
   $$Een onderdeel van het personeelsbeleid is het personeel de mogelijkheid te bieden om zich professioneel te ontwikkelen.$$, 'inline'),
  ('b6edd4a3-cad2-49e1-a1ee-ad19ccbc26df', 'a1e5f658-2e69-46ef-bd0c-1df0f1bcd1a6', $$collectieve aansprakelijkheidsverzekering voor het personeel$$,
   $$bedrijfseconomie-vwo-2021-iii-carolusumc-context6.png$$,
   $$Emma leest ook dat CarolusUMC een collectieve aansprakelijkheidsverzekering voor het personeel heeft afgesloten.$$, 'inline'),
  ('42788271-a5b6-4d82-931d-23f1aeb079a7', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$inleiding: informatiebronnen 1-4, btw-tarief 21%$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context1.png$$,
   $$Bij deze opgave horen de informatiebronnen 1 tot en met 4.
In deze opgave is het btw-tarief 21%.$$, 'inline'),
  ('17863182-7635-40aa-8c00-64a8e1c778cb', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$foto: magazijn met stellingen en dozen$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context2.png$$,
   $$Foto van een magazijn met stellingen vol dozen en een medewerker.$$, 'inline'),
  ('d06bf76b-4f1d-4e8c-81c7-f3c98dbd1c3e', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$Wagenaar bv: opslag voor webshops, vanaf 2015 e-fulfillment (effectuation)$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context3.png$$,
   $$Chris Wagenaar is directeur en enige aandeelhouder van Wagenaar bv, dat hij in 2010 heeft opgericht. Wagenaar bezit een grote loods waarin webshops magazijn- en opslagruimte kunnen huren om hun voorraden extern op te slaan.
In 2015 heeft Wagenaar zijn bedrijfsmodel aangepast: webshops kunnen nu hun gehele orderafhandeling aan Wagenaar uitbesteden. Dit wordt e-fulfillment genoemd (zie informatiebron 1). Uit informatiebron 1 blijkt dat het ondernemersgedrag van Wagenaar sinds 2015 kenmerken heeft van effectuation.$$, 'inline'),
  ('9e87ce6d-157b-44c2-b9fb-d2d59ebb2e14', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$voorraden van klanten off-balance halen$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context4.png$$,
   $$Onderdeel van dit nieuwe bedrijfsmodel is dat Wagenaar zijn klanten de mogelijkheid biedt om hun voorraden off-balance te halen en op te nemen op de balans van Wagenaar.$$, 'inline'),
  ('1e90865d-3407-47f6-87ce-a50243498e1b', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$verschil voor- en nacalculatorisch resultaat 2020: loonkosten orderpickers$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context5.png$$,
   $$In de periode 2015 tot en met 2020 pakt het nieuwe bedrijfsmodel van Wagenaar goed uit. Wel blijkt er uit de analyse van de resultaten over 2020 een groot verschil te zijn tussen het voorcalculatorische en nacalculatorische resultaat (zie informatiebron 2). Dit wordt grotendeels veroorzaakt door een nadelig budgetresultaat op de loonkosten van de orderpickers bij Wagenaar. Hiervoor zijn twee oorzaken:
− de loonkosten per uur
− het aantal minuten per orderpick.$$, 'inline'),
  ('e557c1c6-7bf7-4913-b391-a16bd4f5e60f', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$krapte op de arbeidsmarkt als oorzaak$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context6.png$$,
   $$De oorzaak van dit efficiency- en prijsresultaat is volgens Wagenaar het feit dat er een grote krapte op de arbeidsmarkt is (weinig werklozen en veel openstaande vacatures).$$, 'inline'),
  ('07be5431-de5a-46a1-89d4-b5a571de1882', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$loonkosten van de orderpickers per order als maatstaf$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context7.png$$,
   $$Om de prestaties van de orderpickers over een jaar te meten, hanteert Wagenaar de gerealiseerde loonkosten van de orderpickers per order.$$, 'inline'),
  ('da13ac82-9e3c-45f2-b5d2-05520e506458', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$PI maximaal € 1,50; plan per 1 januari 2021 (onderdelen a en b)$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context8.png$$,
   $$Wagenaar heeft als doel gesteld dat de uitkomst van deze PI maximaal € 1,50 mag zijn. Over 2020 was dit afgerond € 2,41.
Het grote verschil tussen de voor- en nacalculatorische loonkosten van de orderpickers én het niet behalen van de gewenste KPI over 2020 zijn voor Wagenaar aanleiding om een plan op te stellen dat per 1 januari 2021 moet worden uitgevoerd: a investeren in en financiering van een semi-automatisch orderpicksysteem met bijbehorende software (zie informatiebron 4) om het totale aantal benodigde fte te verminderen. én b een aantal orderpickers voor onbepaalde tijd in dienst nemen en daardoor goedkopere orderpickers (uitzendkrachten) dagelijks inhuren via het uitzendbureau (zie informatiebron 3)$$, 'inline'),
  ('692a081f-6329-41ae-81f9-293103f61cab', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$voorwaarden voor het plan; behalen PI 2021: minimumaantal fte orderpickers$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context9.png$$,
   $$Wagenaar zal het plan per 1 januari 2021 uitvoeren indien door het plan:
− de gewenste waarde van de PI over 2021 naar verwachting wordt behaald én
− de verwachte afname van de loonkosten over 2021 van de orderpickers groter is dan de verwachte toename van de overige bedrijfskosten en financieringskosten over 2021.
Behalen PI 2021
Wagenaar zal een minimumaantal fte aan orderpickers voor onbepaalde tijd in dienst nemen. Dit aantal wordt bepaald door het aantal verwachte orders op de minst drukke dag van de week.$$, 'inline'),
  ('f5c68674-aabe-4271-b49a-1e8ff8c36868', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$minimumaantal orderpickers dagelijks inzetbaar, rest uitzendkrachten$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context10.png$$,
   $$Dit minimumaantal orderpickers is elke dag in de week volledig inzetbaar om orders te picken. Indien meer orderpickers op een bepaalde dag nodig zijn, zullen voor die dag uitzendkrachten worden ingehuurd via het eerder genoemde uitzendbureau. Ga voor de berekening van het aantal uitzendkrachten uit van het gemiddelde aantal orders per week.$$, 'inline'),
  ('6b4257ee-4c15-410e-964e-aa8b12135aa0', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$kopje: verwachte toename interestkosten en afschrijvingskosten$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context11.png$$,
   $$Verwachte toename interestkosten en afschrijvingskosten$$, 'inline'),
  ('99f0c46f-890b-46e4-8f01-db36f0b8a5ed', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$investeringen leiden tot hogere afschrijvingskosten$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context12.png$$,
   $$De investeringen in het semi-automatisch orderpicksysteem en de software leiden tot een toename van de afschrijvingskosten.$$, 'inline'),
  ('5d00889e-3d0a-4958-99ae-0d55cd783813', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$kopje: conclusie$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-context13.png$$,
   $$Conclusie$$, 'inline'),
  ('cb4f7511-6031-4b4c-9e16-7c679bddb13b', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$Informatiebron 1: bedrijfsmodel van Wagenaar$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-informatiebron1.png$$,
   $$Informatiebron 1
Bedrijfsmodel van Wagenaar
2010 tot en met 2014: Magazijn- en opslagruimte. Wagenaar biedt webshops de mogelijkheid om magazijn- en opslagruimte te huren om hun voorraden extern op te slaan.
vanaf 2015: Magazijn- en opslagruimte- e-fulfillment. E-fulfillment bij Wagenaar houdt in dat Wagenaar webshops de mogelijkheid biedt om:
1 magazijn- en opslagruimte te huren.
2 de gehele afhandeling (inslag, opslag, orderpicken en verzenden) van hun voorraden uit te besteden aan Wagenaar. Wagenaar heeft hierbij een samenwerkingsovereenkomst met PostNL afgesloten. Het verwerken van de retour verzonden producten is ook onderdeel van e-fulfillment.
3 hun voorraden bedrijfseconomisch over te laten nemen door Wagenaar, door die voorraden op de balans van Wagenaar op te nemen (= off-balance halen bij de klanten van Wagenaar).
Wagenaar heeft bij het besluit om het bedrijfsmodel te veranderen een onderzoek uit 2014 gebruikt. De belangrijkste onderdelen uit dit onderzoek waren:
− De pakketmarkt groeit in hoog tempo. De voornaamste reden is dat consumenten steeds meer online kopen via webshops.
− Ook stellen consumenten steeds hogere eisen aan de bezorging van de producten: “vandaag besteld, morgen in huis” is de standaard geworden.
− Webshops worden snel groter en zullen veel moeten investeren in magazijnruimte en personeel om aan de groeiende vraag en stijgende eisen van de consumenten te kunnen voldoen.
Onder de tabel twee foto''s: een magazijn met stellingen en medewerkers die orders verwerken.$$, 'inline'),
  ('2d60cd14-d595-4b36-9f49-22de5bec1a52', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$Informatiebron 2: voor- en nacalculatorische gegevens Wagenaar 2020$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-informatiebron2.png$$,
   $$Informatiebron 2
Gegevens Wagenaar 2020
Voorcalculatorische en nacalculatorische resultaten van Wagenaar over 2020
| voorcalculatorisch | nacalculatorisch | verschil
omzet | 1.460.000 | 1.551.250 | 91.250
loonkosten orderpickers¹⁾ | 547.500 | 876.000 | -/-²⁾ 328.500
overige bedrijfskosten | 650.000 | 650.000 | 0
bedrijfsresultaat | 262.500 | 25.250 | -/- 237.250
financieringsresultaat | -/- 50.000 | -/- 50.000 | 0
resultaat voor belasting | 212.500 | -/- 24.750 | -/- 237.250
noot 1 Alle orderpickers zijn gezamenlijk verantwoordelijk voor het picken, verpakken en verzenden van de orders. Alle orderpickers zijn uitzendkrachten die dagelijks de gehele dag worden ingehuurd via een uitzendbureau. Er wordt gedurende 365 dagen georderpickt.
noot 2 -/- betekent negatief.
Overige voorcalculatorische en nacalculatorische gegevens van Wagenaar over 2020
gemiddelde | voorcalculatorisch | nacalculatorisch
orders per dag | 1.000 | 1.000
orders per jaar | 365.000 | 365.000
verkooptarief per order | € 4,00 | € 4,25
orderpicktijd per order | 6 minuten | 9 minuten
loonkosten orderpickers per uur | € 15,00 | € 16,00$$, 'inline'),
  ('c0ae6ca5-6886-48ff-8fc2-3a1af36e3b2e', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$Informatiebron 3: verwacht aantal orders per dag in 2021$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-informatiebron3.png$$,
   $$Informatiebron 3
Verwacht aantal orders per dag in iedere week van 2021
Staafdiagram (aantal orders per dag), met een stippellijn voor het wekelijks gemiddelde per dag (1.000): maandag 1.500, dinsdag 800, woensdag 700, donderdag 1.000, vrijdag 1.100, zaterdag 1.300, zondag 600.
Wagenaar verwacht over 2021 dezelfde hoeveelheid orders per jaar en gemiddeld per dag als over 2020. In 2021 wordt gedurende 365 dagen georderpickt.$$, 'inline'),
  ('5d74d3af-576d-49c0-a3bd-453a598a9dac', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$Informatiebron 4: investering en financiering semi-automatisch orderpicksysteem$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-informatiebron4.png$$,
   $$Informatiebron 4
Informatie met betrekking tot onderdeel a van het plan: de investering en financiering
(foto van een semi-automatisch orderpicksysteem)
De aanschafprijzen en afschrijvingen
Aan de hand van opgevraagde offertes, verwacht Wagenaar de volgende uitgaven inclusief 21% btw:
semi-automatisch orderpicksysteem € 484.000
installatie semi-automatisch orderpicksysteem € 60.500 +
totaal € 544.500
software € 36.300
Het semi-automatisch orderpicksysteem (zie afbeelding) inclusief installatie wordt in 10 jaar lineair afgeschreven tot 25% van de totale aanschafwaarde. De software wordt lineair in 10 jaar geheel afgeschreven.
Financiering
Ten behoeve van het bepalen van de extra interestkosten door het plan bepaalt de financieel controller van Wagenaar dat de investering inclusief btw voor 60% met vreemd vermogen gefinancierd moet worden en voor 40% met eigen vermogen.
Het aan te trekken vreemd vermogen zal in 10 jaar lineair worden afgelost. Met ingang van 1 juli 2021 zullen halfjaarlijks, op 1 juli en 31 december, de aflossing en de dan verschuldigde interest (4% per jaar) achteraf worden betaald.$$, 'inline'),
  ('9c723237-f49a-473e-9735-65f740f3523f', '65e3cc6d-f1b2-4f79-8408-2a7e9bf0798d', $$Formuleblad$$,
   $$bedrijfseconomie-vwo-2021-iii-wagenaar-bv-formuleblad.png$$,
   $$Formuleblad
Voor beantwoording van vraag 8 en 17 zijn de volgende formules beschikbaar.
8 efficiencyresultaat = (sh – wh) x sp
prijsresultaat = (sp – wp) x wh
sh = standaardhoeveelheid
wh = werkelijke hoeveelheid
sp = standaardprijs
wp = werkelijke prijs$$, 'inline'),
  ('57387bc6-ab09-472a-9537-bcf61225d472', '08610651-a947-4ed3-a9f3-760a59892370', $$Cornelis Lyceum: jaarlijkse examenreis ingekocht bij LOTTRAVEL$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context1.png$$,
   $$Op het Cornelis Lyceum in Kerkrade gaan de leerlingen van de zesde klas elk jaar in de eerste week van november op examenreis. De reis wordt jaarlijks door de school ingekocht bij LOTTRAVEL.$$, 'inline'),
  ('4c30d688-38e7-4294-8ebf-e8c97245f1b0', '08610651-a947-4ed3-a9f3-760a59892370', $$foto: collage van bezienswaardigheden en een touringcar$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context2.png$$,
   $$Collage van Europese bezienswaardigheden, een vliegtuig en een touringcar.$$, 'inline'),
  ('d9cfbb67-62a7-4c73-a75d-2336c25c6f73', '08610651-a947-4ed3-a9f3-760a59892370', $$reissom per leerling verandert elk jaar$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context3.png$$,
   $$De school betaalt de prijs van de reis (reissom) per leerling aan LOTTRAVEL. De hoogte van deze reissom per leerling verandert elk jaar.$$, 'inline'),
  ('eafc6747-19aa-4808-a107-2ba61789ecb5', '08610651-a947-4ed3-a9f3-760a59892370', $$tabel indexcijfers en reissom per leerling 2017-2021$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context4.png$$,
   $$jaar | 2017 | 2018 | 2019 | 2020 | 2021
indexcijfer reissom per leerling | 98,68 | 102,37 | 101,32 | (grijs) | 107,89
reissom per leerling in euro’s | 375,00 | 389,00 | 385,00 | (grijs) | (vraag 16)$$, 'inline'),
  ('d85c01c9-43e2-4738-a11a-7f9b1c088f46', '08610651-a947-4ed3-a9f3-760a59892370', $$sparen voor de reis met maandelijkse stortingen en subsidie$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context5.png$$,
   $$De leerlingen, die in augustus 2019 in vwo 4 zijn gestart, zijn in 2021 op examenreis geweest. Voor deze reis ontvangt de school Europese subsidie. Hiermee kan een deel van de reissom betaald worden. Het grootste deel wordt betaald door de leerlingen zelf.
− De totale reissom (aantal leerlingen x antwoord op vraag 16) is door de school op 1 november 2021 aan LOTTRAVEL overgemaakt.
− Met ingang van 31 augustus 2019 hebben de leerlingen elke maand op de laatste dag van de maand € 10 op een speciaal voor deze reis geopende spaarrekening gestort. De laatste stortingen vonden plaats op 31 oktober 2021. De spaarrekening vergoedde maandelijks 0,15% samengestelde interest, die steeds op de laatste dag van de maand werd bijgeschreven.
− Op dezelfde spaarrekening is op 1 september 2020 door de school uit de subsidiepot een bedrag bijgestort, zodat op 1 november 2021 exact de betaling aan LOTTRAVEL gedaan kon worden.$$, 'inline'),
  ('c774bac9-4dc5-4641-bf39-f4724a4d38fa', '08610651-a947-4ed3-a9f3-760a59892370', $$56 leerlingen sparen en gaan mee$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context6.png$$,
   $$Er zijn 56 leerlingen die in 2019 begonnen zijn met sparen en in 2021 zijn meegegaan op examenreis. Doubleurs en instromers worden buiten beschouwing gelaten.$$, 'inline'),
  ('d911c7ee-4ca6-4bb4-990f-e118c8afb352', '08610651-a947-4ed3-a9f3-760a59892370', $$overboekt hotel opgelost door de serviceafdeling van LOTTRAVEL$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-context7.png$$,
   $$Tijdens de examenreis blijkt dat het hotel waarin de leerlingen zouden overnachten, is overboekt: veel kamers waren dubbel verhuurd, waardoor er moest worden uitgeweken naar een ander hotel. De serviceafdeling van LOTTRAVEL heeft dit alles tot tevredenheid van de school geregeld.$$, 'inline'),
  ('e74a9063-1f75-445f-980b-df096f7d2ebd', '08610651-a947-4ed3-a9f3-760a59892370', $$Formuleblad$$,
   $$bedrijfseconomie-vwo-2021-iii-cornelis-lyceum-formuleblad.png$$,
   $$Formuleblad
Voor beantwoording van vraag 8 is de volgende formule beschikbaar.
17 somformule meetkundige reeks:
S = a x (rⁿ − 1) / (r − 1)
hierbij gebruikte symbolen:
S = som van de getallen in een meetkundige reeks
a = aanvangsterm van de meetkundige reeks
r = reden van de meetkundige reeks
n = aantal termen van de meetkundige reeks$$, 'inline'),
  ('114322cf-cd14-4339-b41f-9acdb798e65e', '9cdf3c23-b7a8-42c0-a814-4c4b04aaf160', $$In deze opgave wordt gerekend met twee verschillende btw-tarieven.$$,
